import "core-js/modules/es.array.push.js";
import SnackBar from "@/components/SnackBar.vue";
import CreateBroadcast from "@/components/Broadcast/BroadcastPopups/CreateBroadcast.vue";
import BroadcastChatview from "./BroadcastChatview.vue";
import BroadcastMessages from "./BroadcastMessages.vue";
import GroupChat from "./GroupChat.vue";
import CreateGroupchat from "./BroadcastPopups/CreateGroupchat.vue";
export default {
  components: {
    GroupChat,
    SnackBar,
    BroadcastMessages,
    BroadcastChatview,
    CreateGroupchat,
    CreateBroadcast
  },
  data: () => ({
    toggle_exclusive: "broadchat_view",
    annoucementDialog: false,
    groupDialog: false,
    componentCheck: 0,
    messagehat: 0,
    chatgroup: 0,
    SnackBarComponent: {}
  }),
  methods: {
    createGroup() {
      this.componentCheck = 2;
      this.groupDialog = true;
    },
    create_annoucement() {
      this.componentCheck = 1;
      this.annoucementDialog = true;
    },
    back_call() {
      this.$router.push("/UserlevelApp");
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.messagehat++;
      this.annoucementDialog = false;
    },
    success_infogroup(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.chatgroup++;
      this.groupDialog = false;
    }
  }
};
